function maxDepth(s) {
  let depth = 0
  let best = 0
  for (const ch of s) {
    if (ch === '(') {
      depth += 1
      if (depth > best) best = depth
    } else if (ch === ')') {
      depth -= 1
    }
  }
  return best
}

